}

Simple_Selector_Obj Parser::parse_pseudo_selector() {
  if (lex< sequence<
        pseudo_prefix,
        // we keep the space within the name, strange enough
        // ToDo: refactor output to schedule the space for it
        // or do we really want to keep the real white-space?
        sequence< identifier, optional < block_comment >, exactly<'('> >
      > >())
  {

    std::string name(lexed);
    name.erase(name.size() - 1);
    ParserState p = pstate;

    // specially parse static stuff
    // ToDo: really everything static?
    if (peek_css <
          sequence <
            alternatives <
              static_value,
              binomial
            >,
            optional_css_whitespace,
            exactly<')'>
          >
        >()
    ) {
      lex_css< alternatives < static_value, binomial > >();
      String_Constant_Obj expr = SASS_MEMORY_NEW(String_Constant, pstate, lexed);
      if (lex_css< exactly<')'> >()) {
        expr->can_compress_whitespace(true);
        return SASS_MEMORY_NEW(Pseudo_Selector, p, name, expr);
      }
    }
    else if (Selector_List_Obj wrapped = parse_selector_list(true)) {
      if (wrapped && lex_css< exactly<')'> >()) {
        return SASS_MEMORY_NEW(Wrapped_Selector, p, name, wrapped);
      }
    }

  }
  // EO if pseudo selector

  else if (lex < sequence< optional < pseudo_prefix >, identifier > >()) {
    return SASS_MEMORY_NEW(Pseudo_Selector, pstate, lexed);
  }
  else if(lex < pseudo_prefix >()) {
    css_error("Invalid CSS", " after ", ": expected pseudoclass or pseudoelement, was ");
  }

  css_error("Invalid CSS", " after ", ": expected \")\", was ");

  // unreachable statement
  return {};
}

static bool ok_inflater_compressed_block(ok_inflater *inflater) {
    const bool is_fixed = inflater->state == OK_INFLATER_STATE_READING_FIXED_COMPRESSED_BLOCK;
    const ok_inflater_huffman_tree *literal_tree =
        (is_fixed ? inflater->fixed_literal_huffman : inflater->literal_huffman);
    const ok_inflater_huffman_tree *distance_tree =
        (is_fixed ? inflater->fixed_distance_huffman : inflater->distance_huffman);

    // decode literal/length value from input stream

    size_t max_write = ok_inflater_can_write_total(inflater);
    const uint16_t *tree_lookup_table = literal_tree->lookup_table;
    const unsigned int tree_bits = literal_tree->bits;
    while (max_write > 0) {
        int value = ok_inflater_decode_literal(inflater, tree_lookup_table, tree_bits);
        if (value < 0) {
            // Needs input
            return false;
        } else if (value < 256) {
            ok_inflater_write_byte(inflater, (uint8_t)value);
            max_write--;
        } else if (value == 256) {
            inflater->state = OK_INFLATER_STATE_READY_FOR_NEXT_BLOCK;
            return true;
        } else if (value < 286) {
            inflater->huffman_code = value - 257;
            inflater->state_count = -1;
            inflater->state_distance = -1;
            if (ok_inflater_distance_with_tree(inflater, distance_tree)) {
                max_write = ok_inflater_can_write_total(inflater);
            } else {
                if (is_fixed) {
                    inflater->state = OK_INFLATER_STATE_READING_FIXED_DISTANCE;
                } else {
                    inflater->state = OK_INFLATER_STATE_READING_DYNAMIC_DISTANCE;
                }
                return false;
            }
        } else {
            ok_inflater_error(inflater, "Invalid inflater literal");
            return false;
        }
    }
    // Output buffer full
    return false;
}

psutil_proc_suspend_or_resume(PyObject *self, PyObject *args) {
    long pid;
    NTSTATUS status;
    HANDLE hProcess;
    PyObject* suspend;

    if (! PyArg_ParseTuple(args, "lO", &pid, &suspend))
        return NULL;

    hProcess = psutil_handle_from_pid(pid, PROCESS_SUSPEND_RESUME);
    if (hProcess == NULL)
        return NULL;

    if (PyObject_IsTrue(suspend))
        status = psutil_NtSuspendProcess(hProcess);
    else
        status = psutil_NtResumeProcess(hProcess);

    if (! NT_SUCCESS(status)) {
        CloseHandle(hProcess);
        return psutil_SetFromNTStatusErr(status, "NtSuspend|ResumeProcess");
    }

    CloseHandle(hProcess);
    Py_RETURN_NONE;
}

